/**
 * Writes shared/domain/pawn-files.generated.ts: the pawn art filenames under
 * frontend/public/pawns/<folder>/.
 *
 *   bun run pawns:files
 *
 * Run it after you add, rename or remove pawn art. The list is the one set of
 * pawn skins that the app offers, that the server accepts from a player or a
 * bot, and that a viewer draws (board task 6a245eee). It is a generated file,
 * not a read of the folder at run time: the browser bundle needs it too, and
 * the production image keeps no frontend/public. tests/pawn-skins.test.ts
 * fails when the file and the folders disagree.
 */
import { readdirSync, writeFileSync } from "node:fs";
import path from "node:path";
import { spawnSync } from "node:child_process";

const ROOT = path.resolve(import.meta.dir, "..");
const PAWNS_DIR = path.join(ROOT, "frontend/public/pawns");
export const PAWN_FILES_MODULE = path.join(
  ROOT,
  "shared/domain/pawn-files.generated.ts",
);

/** Each pawn folder and its SVG filenames, both sorted. */
export const readPawnFiles = (): Record<string, string[]> =>
  Object.fromEntries(
    readdirSync(PAWNS_DIR, { withFileTypes: true })
      .filter((entry) => entry.isDirectory())
      .map((entry) => entry.name)
      .sort()
      .map((folder) => [
        folder,
        readdirSync(path.join(PAWNS_DIR, folder))
          .filter((name) => name.endsWith(".svg"))
          .sort(),
      ]),
  );

if (import.meta.main) {
  const source = `// GENERATED by scripts/generate-pawn-files.ts from frontend/public/pawns.
// Do not edit by hand: run \`bun run pawns:files\`.

/** The SVG filenames in each folder of frontend/public/pawns, sorted. */
export const PAWN_FILES = ${JSON.stringify(readPawnFiles(), null, 2)} satisfies Record<string, readonly string[]>;
`;
  writeFileSync(PAWN_FILES_MODULE, source);
  const prettier = spawnSync(
    "bun",
    ["x", "prettier", "--write", PAWN_FILES_MODULE],
    {
      cwd: ROOT,
      stdio: "inherit",
    },
  );
  if (prettier.status !== 0) process.exit(prettier.status ?? 1);
  console.log(`wrote ${path.relative(ROOT, PAWN_FILES_MODULE)}`);
}
